say("Let us work out the quadratic formula on paper.");
const area = paper(260, 140, 520, 380, { title: "Algebra", heading: "Quadratic Roots", subtitle: "ax^2 + bx + c = 0" });
write(area.x + 20, area.y + 40, "Discriminant: b^2 - 4ac");
